'use client';

import { useRouter } from 'next/navigation';
import { Icon } from '@/components/Icon';
import { Avatar } from '@/components/Avatar';
import { useApp } from '@/hooks/useApp';
import { useState, useEffect } from 'react';
import { SearchField } from '@/components/SearchField';

const allEnvironments = [
  { id: '1', name: 'Paróquia Santo Antônio', location: 'Bairro Jardins, São Paulo', type: 'church', image: 'https://images.unsplash.com/photo-1519491050282-cf00c82424b4?w=200' },
  { id: '2', name: 'Condomínio Solar das Palmeiras', location: 'Vila Olímpia, São Paulo', type: 'residential', image: 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=200' },
  { id: '3', name: 'Clube União', location: 'Centro, São Paulo', type: 'club', image: 'https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=200' },
  { id: '4', name: 'Associação dos Moradores', location: 'Brooklyn, São Paulo', type: 'association', image: 'https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=200' },
  { id: '5', name: 'Igreja Batista Central', location: 'Sé, São Paulo', type: 'church', image: 'data:image/jpeg;base64,' },
  { id: '6', name: 'Condomínio Village', location: 'Pinheiros, São Paulo', type: 'residential', image: 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=200' },
  { id: '7', name: 'Clube Esperança', location: 'Moema, São Paulo', type: 'club', image: 'data:image/jpeg;base64,' },
  { id: '8', name: 'Associação Cultural', location: 'Vila Mariana, São Paulo', type: 'association', image: 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?w=200' },
  { id: '9', name: 'Condomínio Acqua', location: 'Itaim Bibi, São Paulo', type: 'residential', image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=200' },
  { id: '10', name: 'Paróquia Nossa Senhora', location: 'Perdizes, São Paulo', type: 'church', image: 'data:image/jpeg;base64,' },
  { id: '11', name: 'Clube Regatas', location: 'Santana, São Paulo', type: 'club', image: 'data:image/png;base64,' },
  { id: '12', name: 'Associação Comercial', location: 'Liberdade, São Paulo', type: 'association', image: 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=200' },  
];

const categories = [
  { id: 'all', label: 'Tudo', type: null },
  { id: 'church', label: 'Igrejas', type: 'church' },
  { id: 'residential', label: 'Condomínios', type: 'residential' },
  { id: 'club', label: 'Clubes', type: 'club' },
  { id: 'association', label: 'Associações', type: 'association' },
];

interface EnvOption {
  id: string;
  name: string;
  location: string;
  type: string;
  image: string;
}

export default function ExplorePage() {
  const router = useRouter();
  const { setSelectedEnvironments, selectedEnvironments, user } = useApp();
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [selectedEnv, setSelectedEnv] = useState<EnvOption | null>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const toSafeLower = (value: unknown) =>
    typeof value === 'string' ? value.toLowerCase() : '';

  const filteredEnvironments = allEnvironments.filter(env => {
    const matchesSearch =
      toSafeLower(env.name).includes(search.toLowerCase()) ||
      toSafeLower(env.location).includes(search.toLowerCase());
    const matchesCategory = selectedCategory === 'all' || env.type === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const handleEnvClick = (env: EnvOption) => {
    setSelectedEnv(env);
    setShowConfirmModal(true);
  };

  const handleConfirm = () => {
    if (selectedEnv) {
      const slug = selectedEnv.name
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '');

      const newEnv = {
        id: selectedEnv.id,
        slug,
        name: selectedEnv.name,
        location: selectedEnv.location,
        type: selectedEnv.type as 'church' | 'residential' | 'club' | 'association',
        image: selectedEnv.image,
        members: 0,
        isSelected: true,
        status: 'active'
      };
      
      const envAlreadyExists = selectedEnvironments.some(e => e.id === selectedEnv.id);
      
      if (!envAlreadyExists) {
        setSelectedEnvironments([...selectedEnvironments, newEnv]);
      }
      
      setShowConfirmModal(false);
      router.push('/places');
    }
  };

  const handleViewServices = (env: EnvOption) => {
    const existingEnv = selectedEnvironments.find(e => e.id === env.id);
    if (existingEnv) {
      router.push('/');
    } else {
      handleEnvClick(env);
    }
  };

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      church: 'Igreja',
      residential: 'Condomínio',
      club: 'Clube',
      association: 'Associação'
    };
    return labels[type] || type;
  };

  return (
    <div className="min-h-screen pb-24 bg-background">
      <header className="fixed top-0 w-full z-50 bg-surface-container-lowest/85 backdrop-blur-xl flex items-center justify-between px-4 h-16 md:border-b md:border-outline-variant/20">
        <div className="flex items-center gap-3 max-w-7xl mx-auto w-full">
          <button 
            onClick={() => router.back()}
            className="hover:bg-surface-container-high/70 rounded-full transition-colors p-2 active:scale-95 duration-200 text-primary"
          >
            <Icon icon="arrow_back" size={24} />
          </button>
          <h1 className="text-lg font-semibold tracking-tight text-on-surface">Explorar Ambientes</h1>
        </div>
        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
          {mounted && user ? (
            <button onClick={() => router.push('/profile')} className="hover:scale-105 transition-transform active:scale-95 ml-1">
              <Avatar
                src={user.avatar}
                name={user.name}
                alt="Avatar"
                className="w-10 h-10 border-2 border-primary shadow-sm"
              />
            </button>
          ) : (
            <button 
              onClick={() => router.push('/login')}
              className="flex items-center gap-2 px-4 py-2 rounded-full primary-gradient text-white text-xs font-bold shadow-lg shadow-primary/20 active:scale-95 transition-all"
            >
              <Icon icon="login" size={20} />
              <span>Entrar</span>
            </button>
          )}
        </div>
      </header>

      <main className="pt-20 px-4 md:px-8 max-w-3xl mx-auto space-y-6">
        <SearchField
          value={search}
          onChange={setSearch}
          placeholder="Buscar ambientes..."
        />
        
        <div className="flex gap-2 overflow-x-auto no-scrollbar">
          {categories.map((cat) => (
            <button 
              key={cat.id} 
              onClick={() => setSelectedCategory(cat.id)}
              className={`px-6 py-2.5 rounded-full text-sm font-bold whitespace-nowrap active:scale-95 transition-all ${
                selectedCategory === cat.id 
                  ? 'primary-gradient text-white shadow-md shadow-primary/20' 
                  : 'bg-surface-container-low text-on-surface-variant hover:bg-surface-container-high'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>
        
        <section className="space-y-3">
          {filteredEnvironments.length === 0 ? (
            <div className="text-center py-10 opacity-50">
              <Icon icon="location_off" weight={400} size={48} className="mb-2 text-outline mx-auto" />
              <p className="text-sm">Nenhum ambiente encontrado.</p>
            </div>
          ) : (
            filteredEnvironments.map((env) => {
              const isAdded = selectedEnvironments.some(e => e.id === env.id);
              return (
                <div 
                  key={env.id} 
                  className="bg-surface-container-lowest p-4 rounded-2xl flex items-center gap-4 hover:bg-surface-container-low transition-colors cursor-pointer"
                  onClick={() => handleViewServices(env)}
                >
                  <img className="w-16 h-16 rounded-full object-cover" src={env.image} alt={env.name} loading="lazy" decoding="async" />
                  <div className="flex-1">
                    <h3 className="font-bold text-on-surface">{env.name}</h3>
                    <p className="text-on-surface-variant text-sm">{env.location}</p>
                    <span className="text-xs text-primary font-medium">{getTypeLabel(env.type)}</span>
                  </div>
                  {isAdded ? (
                    <div className="flex items-center gap-2 text-primary">
                      <Icon icon="check_circle" weight={400} size={24} style={{ fontVariationSettings: "'FILL' 1" }} />
                      <span className="text-xs font-bold">Adicionado</span>
                    </div>
                  ) : (
                    <Icon icon="chevron_right" weight={400} size={24} className="text-on-surface-variant" />
                  )}
                </div>
              );
            })
          )}
        </section>
      </main>

      {showConfirmModal && selectedEnv && (
          <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-surface-container-lowest rounded-3xl p-6 max-w-sm w-full shadow-2xl border border-outline-variant/10">
            <div className="flex items-center gap-4 mb-4">
              <img className="w-16 h-16 rounded-full object-cover" src={selectedEnv.image} alt={selectedEnv.name} loading="lazy" decoding="async" />
              <div>
                <h3 className="font-bold text-on-surface text-lg">{selectedEnv.name}</h3>
                <p className="text-on-surface-variant text-sm">{getTypeLabel(selectedEnv.type)}</p>
              </div>
            </div>
            <p className="text-on-surface-variant mb-6">
              Você confirma que faz parte deste ambiente? Ao confirmar, você poderá visualizar os serviços disponíveis aqui.
            </p>
            <div className="flex gap-3">
              <button 
                onClick={() => setShowConfirmModal(false)}
                className="flex-1 py-3 rounded-full border-2 border-surface-variant text-on-surface-variant font-bold"
              >
                Cancelar
              </button>
              <button 
                onClick={handleConfirm}
                className="flex-1 py-3 rounded-full primary-gradient text-white font-bold"
              >
                Confirmar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
